(window.__qhadithX=window.__qhadithX||{})[20]={"4":[{"c":"Muwatta Malik","r":"Book 20, Hadith 715","u":"https://quranx.com/Hadith/Malik/In-Book/Book-20/Hadith-715","x":"Yahya related to me from Malik from Nafi from Abdullah ibn Umar that a man once asked the Messenger of Allah, may Allah bless him and grant him peace, what clothes someone in ihram could wear, and the Messenger of Allah, may Allah bless him and grant him peace, said, \"Do not wear shirts, turbans, trousers, burnouses, or leather socks, except if you cannot find sandals. In that case you can wear leather socks, but cut them off below the ankles. Do not wear any clothes that have been touched by saffron or yellow dye.\" Yahya said that Malik was asked about the hadith attributed to the Prophet, may Allah bless him and grant him peace, \"Whoever cannot find a waist wrapper should wear trousers,\" and he said, \"I have never heard this, and I do not think that some one who is in ihram can wear trousers, because among the things which the Prophet, may Allah bless him and grant him peace, forbade some one in ihram to wear were trousers, and he did not make any exception for them although he did make an exception for leather socks.\" 20.4 Wearing Clothes when in Ihram","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم مَا يَلْبَسُ الْمُحْرِمُ مِنَ الثِّيَابِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ تَلْبَسُوا الْقُمُصَ وَلاَ الْعَمَائِمَ وَلاَ السَّرَاوِيلاَتِ وَلاَ الْبَرَانِسَ وَلاَ الْخِفَافَ إِلاَّ أَحَدٌ لاَ يَجِدُ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنَ الْكَعْبَيْنِ وَلاَ تَلْبَسُوا مِنَ الثِّيَابِ شَيْئًا مَسَّهُ الزَّعْفَرَانُ وَلاَ الْوَرْسُ ‏.‏","v":[]}],"7":[{"c":"Muwatta Malik","r":"Book 20, Hadith 725","u":"https://quranx.com/Hadith/Malik/In-Book/Book-20/Hadith-725","x":"Yahya related to me from Malik from Hisham ibn Urwa that Fatima bint al-Mundhir said, \"We used to veil our faces when we were in ihram in the company of Asma bint Abi Bakr as-Siddiq.\" 20.7 Wearing Perfume during Hajj.","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ فَاطِمَةَ بِنْتِ الْمُنْذِرِ، أَنَّهَا قَالَتْ كُنَّا نُخَمِّرُ وُجُوهَنَا وَنَحْنُ مُحْرِمَاتٌ وَنَحْنُ مَعَ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ ‏.‏","v":[]}],"12":[{"c":"Muwatta Malik","r":"Book 48, Hadith 1670","u":"https://quranx.com/Hadith/Malik/In-Book/Book-48/Hadith-1670","x":"Yahya related to me from Malik from his paternal uncle Abu Suhayl ibn Malik from his father that Kab al-Ahbar said to a man who took off his sandals, \"Why have you taken off your sandals? Perhaps you have interpreted this ayat, 'Remove your sandals. You are in the pure valley of Tuwa?' (Sura 20 ayat 12) Do you know what the sandals of Musa were?\" Malik (the father of Abu Suhayl) said, \"I do not know what the man answered.\" Kab said, \"They were made from the skin of a dead donkey.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَمِّهِ أَبِي سُهَيْلِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، عَنْ كَعْبِ الأَحْبَارِ، أَنَّ رَجُلاً، نَزَعَ نَعْلَيْهِ فَقَالَ لِمَ خَلَعْتَ نَعْلَيْكَ لَعَلَّكَ تَأَوَّلْتَ هَذِهِ الآيَةَ ‏{‏فَاخْلَعْ نَعْلَيْكَ إِنَّكَ بِالْوَادِي الْمُقَدَّسِ طُوًى‏}‏ قَالَ ثُمَّ قَالَ كَعْبٌ لِلرَّجُلِ أَتَدْرِي مَا كَانَتْ نَعْلاَ مُوسَى قَالَ مَالِكٌ لاَ أَدْرِي مَا أَجَابَهُ الرَّجُلُ فَقَالَ كَعْبٌ كَانَتَا مِنْ جِلْدِ حِمَارٍ مَيِّتٍ ‏.‏","v":[]}],"14":[{"c":"Sunan Abu Dawud","r":"Hadith 435","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-435","x":"Abu Hurairah reported:\n\nWhen the Messenger of Allah (ﷺ) returned from the Battle of Khaibar, he travelled during the night. When we felt sleep, he halted for rest. Addressing Bilal he said: Keep vigilance at night for us. But Bilal who was leaning against the saddle of his mount was dominated by sleep. Neither the Prophet (ﷺ) nor Bilal nor any of his Companions could get up till the sunshine struck them. The Messenger of Allah (ﷺ) got up first of all. The Messenger of Allah (ﷺ) was embarrassed and said: O Bilal ! He replied: He who detained your soul, detained my soul, Messenger of Allah, my parents be sacrificed for you. Then they drove their mounts to a little distance. The Prophet (ﷺ) perfumed ablution and commanded Bilal who made announcement for the prayer. He (the Prophet) led them in the Fajr prayer. When he finished prayer, he said: If anyone forget saying prayer, he should observe it when he recalls it, for Allah has said (in the Qur'an): \"Establish prayer for my remembrance\". Yunus said: Ibn Shihab used to recite this verse in a similar way (i.e. instead of reciting the word li-dhikri - for the sake of My remembrance - he would recite li-dhikra - when you remember). Ahmad (one of the narrator) said: 'Anbasah (a reporter) reported on the authority of Yunus the word li-dhikri (for the sake of my remembrance). Ahmad said: The word nu'as (occurring in this tradition) means \"drowsiness\".","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنِ ابْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حِينَ قَفَلَ مِنْ غَزْوَةِ خَيْبَرَ فَسَارَ لَيْلَةً حَتَّى إِذَا أَدْرَكَنَا الْكَرَى عَرَّسَ وَقَالَ لِبِلاَلٍ ‏\"‏ اكْلأْ لَنَا اللَّيْلَ ‏\"‏ ‏.‏ قَالَ فَغَلَبَتْ بِلاَلاً عَيْنَاهُ وَهُوَ مُسْتَنِدٌ إِلَى رَاحِلَتِهِ فَلَمْ يَسْتَيْقِظِ النَّبِيُّ صلى الله عليه وسلم وَلاَ بِلاَلٌ وَلاَ أَحَدٌ مِنْ أَصْحَابِهِ حَتَّى إِذَا ضَرَبَتْهُمُ الشَّمْسُ فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَوَّلَهُمُ اسْتِيقَاظًا فَفَزِعَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ يَا بِلاَلُ ‏\"‏ ‏.‏ فَقَالَ أَخَذَ بِنَفْسِي الَّذِي أَخَذَ بِنَفْسِكَ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ فَاقْتَادُوا رَوَاحِلَهُمْ شَيْئًا ثُمَّ تَوَضَّأَ النَّبِيُّ صلى الله عليه وسلم وَأَمَرَ بِلاَلاً فَأَقَامَ لَهُمُ الصَّلاَةَ وَصَلَّى بِهِمُ الصُّبْحَ فَلَمَّا قَضَى الصَّلاَةَ قَالَ ‏\"‏ مَنْ نَسِيَ صَلاَةً فَلْيُصَلِّهَا إِذَا ذَكَرَهَا فَإِنَّ اللَّهَ تَعَالَى قَالَ ‏{‏ أَقِمِ الصَّلاَةَ لِلذِّكْرَى ‏}‏ ‏\"‏ ‏.‏ قَالَ يُونُسُ وَكَانَ ابْنُ شِهَابٍ يَقْرَؤُهَا كَذَلِكَ ‏.‏ قَالَ أَحْمَدُ قَالَ عَنْبَسَةُ - يَعْنِي عَنْ يُونُسَ - فِي هَذَا الْحَدِيثِ لِذِكْرِي ‏.‏ وَقَالَ أَحْمَدُ الْكَرَى النُّعَاسُ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 597","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-597","x":"Narrated Anas:\n\nThe Prophet (ﷺ) said, \"If anyone forgets a prayer he should pray that prayer when he remembers it. There is no expiation except to pray the same.\" Then he recited: \"Establish prayer for My (i.e. Allah's) remembrance.\" (20.14).","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، وَمُوسَى بْنُ إِسْمَاعِيلَ، قَالاَ حَدَّثَنَا هَمَّامٌ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ مَنْ نَسِيَ صَلاَةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لاَ كَفَّارَةَ لَهَا إِلاَّ ذَلِكَ ‏\"‏‏.‏ ‏{‏وَأَقِمِ الصَّلاَةَ لِذِكْرِي‏}‏ قَالَ مُوسَى قَالَ هَمَّامٌ سَمِعْتُهُ يَقُولُ بَعْدُ ‏{‏وَأَقِمِ الصَّلاَةَ لِذِكْرِي‏}‏‏.‏وَقَالَ حَبَّانُ حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا قَتَادَةُ، حَدَّثَنَا أَنَسٌ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 680a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-680a","x":"Abu Huraira reported that when the Messenger of Allah (ﷺ) returned from the expedition to Khaibar, he travelled one night, and stopped for rest when he became sleepy. He told Bilal to remain on guard during the night and he (Bilal) prayed as much as he could, while the Messenger of Allah (ﷺ) and his Companions slept. When the time for dawn approached Bilal leaned against his camel facing the direction from which the dawn would appear but he was overcome by sleep while he was leaning against his camel, and neither the Messenger of Allah (ﷺ) nor Bilal, nor anyone else among his Companions got up, till the sun shone on them. Allah's Messenger (ﷺ) was the first of them to awake and, being startled, he called to Bilal who said:\n\nMessenger of Allah I may my father and mother be offered as ransom for thee, the same thing overpowered me which overpowered you. He (the Holy Prophet, then) said: Lead the beasts on: so they led their camels to some distance. The Messenger of Allah (ﷺ) then performed ablution and gave orders to Bilal who pronounced the Iqama and then led them in the morning prayer. When he finished the prayer he said: When anyone forgets the prayer, he should observe it when he remembers it, for Allah has said:\" And observe the prayer for remembrance of Me\" (Qur'an. xx. 14). Yunus said: Ibn Shilab used to recite it like this:\" (And observe the prayer) for remembrance.\"","ar":"حَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم حِينَ قَفَلَ مِنْ غَزْوَةِ خَيْبَرَ سَارَ لَيْلَهُ حَتَّى إِذَا أَدْرَكَهُ الْكَرَى عَرَّسَ وَقَالَ لِبِلاَلٍ ‏\"‏ اكْلأْ لَنَا اللَّيْلَ ‏\"‏ ‏.‏ فَصَلَّى بِلاَلٌ مَا قُدِّرَ لَهُ وَنَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَصْحَابُهُ فَلَمَّا تَقَارَبَ الْفَجْرُ اسْتَنَدَ بِلاَلٌ إِلَى رَاحِلَتِهِ مُوَاجِهَ الْفَجْرِ فَغَلَبَتْ بِلاَلاً عَيْنَاهُ وَهُوَ مُسْتَنِدٌ إِلَى رَاحِلَتِهِ فَلَمْ يَسْتَيْقِظْ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلاَ بِلاَلٌ وَلاَ أَحَدٌ مِنْ أَصْحَابِهِ حَتَّى ضَرَبَتْهُمُ الشَّمْسُ فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَوَّلَهُمُ اسْتِيقَاظًا فَفَزِعَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ أَىْ بِلاَلُ ‏\"‏ ‏.‏ فَقَالَ بِلاَلٌ أَخَذَ بِنَفْسِي الَّذِي أَخَذَ - بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ - بِنَفْسِكَ قَالَ ‏\"‏ اقْتَادُوا ‏\"‏ ‏.‏ فَاقْتَادُوا رَوَاحِلَهُمْ شَيْئًا ثُمَّ تَوَضَّأَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَمَرَ بِلاَلاً فَأَقَامَ الصَّلاَةَ فَصَلَّى بِهِمُ الصُّبْحَ فَلَمَّا قَضَى الصَّلاَةَ قَالَ ‏\"‏ مَنْ نَسِيَ الصَّلاَةَ فَلْيُصَلِّهَا إِذَا ذَكَرَهَا فَإِنَّ اللَّهَ قَالَ ‏{‏ أَقِمِ الصَّلاَةَ لِذِكْرِي‏}‏ ‏\"‏ ‏.‏ قَالَ يُونُسُ وَكَانَ ابْنُ شِهَابٍ يَقْرَؤُهَا لِلذِّكْرَى ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3163","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3163","x":"Narrated Abu Hurairah:\n\n\"While the Messenger of Allah (ﷺ) was returning from Khaibar he traveled during the night until he became sleepy and he sat down to rest. Then he said: 'O Bilal! Stand guard for us for the night.'\" He said: 'So Bilal performed Salat, then he leaned against his mount facing the direction of (dawn awaiting) Fajr. His eyes overcame him until he slept, and not one of them awoke. The first of them to awaken was the Prophet (ﷺ) who said: 'O Bilal!' Bilal said: 'May my father be ransomed for you O Messenger of Allah! I was overtaken just as you were overtaken.' So the Messenger of Allah (ﷺ) said: 'Move out!' Then he kneeled to perform Wudu and to announce the standing for the Salat, then he performed Salat the same as he would when not traveling. Then he said: 'And establish the Salat for My rememberance (20:14).'\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا النَّضْرُ بْنُ شُمَيْلٍ، أَخْبَرَنَا صَالِحُ بْنُ أَبِي الأَخْضَرِ، عَنِ الزُّهْرِيِّ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا قَفَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنْ خَيْبَرَ أَسْرَى لَيْلَةً حَتَّى أَدْرَكَهُ الْكَرَى أَنَاخَ فَعَرَّسَ ثُمَّ قَالَ ‏\"‏ يَا بِلاَلُ اكْلأْ لَنَا اللَّيْلَةَ ‏\"‏ ‏.‏ قَالَ فَصَلَّى بِلاَلٌ ثُمَّ تَسَانَدَ إِلَى رَاحِلَتِهِ مُسْتَقْبَلَ الْفَجْرِ فَغَلَبَتْهُ عَيْنَاهُ فَنَامَ فَلَمْ يَسْتَيْقِظْ أَحَدٌ مِنْهُمْ وَكَانَ أَوَّلَهُمُ اسْتِيقَاظًا النَّبِيُّ صلى الله عليه وسلم ‏.‏ فَقَالَ ‏\"‏ أَىْ بِلاَلُ ‏\"‏ ‏.‏ فَقَالَ بِلاَلٌ بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ أَخَذَ بِنَفْسِي الَّذِي أَخَذَ بِنَفْسِكَ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اقْتَادُوا ‏\"‏ ‏.‏ ثُمَّ أَنَاخَ فَتَوَضَّأَ فَأَقَامَ الصَّلاَةَ ثُمَّ صَلَّى مِثْلَ صَلاَتِهِ لِلْوَقْتِ فِي تَمَكُّثٍ ثُمَّ قَالَ ‏:‏ ‏(‏وأقِمِ الصَّلاَةَ لِذِكْرِي ‏)‏ ‏.‏ قَالَ هَذَا حَدِيثٌ غَيْرُ مَحْفُوظٍ رَوَاهُ غَيْرُ وَاحِدٍ مِنَ الْحُفَّاظِ عَنِ الزُّهْرِيِّ عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ أَنَّ النَّبِيَّ صلى الله عليه وسلم وَلَمْ يَذْكُرُوا فِيهِ عَنْ أَبِي هُرَيْرَةَ ‏.‏ وَصَالِحُ بْنُ أَبِي الأَخْضَرِ يُضَعَّفُ فِي الْحَدِيثِ ضَعَّفَهُ يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ وَغَيْرُهُ مِنْ قِبَلِ حِفْظِهِ ‏.‏","v":[]}],"40":[{"c":"Sahih Muslim","r":"Hadith 2905f","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2905f","x":"Ibn Fudail reported on the authority of his father that he heard Salim b. `Abdullah b. `Umar as saying:\n\nO people of Iraq, how strange it is that you ask about the minor sins but commit major sins? I heard from my father `Abdullah b. `Umar, narrating that he heard Allah's Messenger (ﷺ) as saying while pointing his hand towards the east: Verily, the turmoil would come from this side, from where appear the horns of Satan and you would strike the necks of one another; and Moses killed a person from among the people of Pharaoh unintentionally and Allah, the Exalted and Glorious, said: \"You killed a person but We relieved you from the grief and tried you with (many a) trial\" (xx. 40). Ahmad b. `Umar reported this hadith from Salim, but he did not make a mention of the words: \"I heard\".","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ أَبَانَ، وَوَاصِلُ بْنُ عَبْدِ الأَعْلَى، وَأَحْمَدُ بْنُ عُمَرَ الْوَكِيعِيُّ، - وَاللَّفْظُ لاِبْنِ أَبَانَ - قَالُوا حَدَّثَنَا ابْنُ فُضَيْلٍ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ سَالِمَ بْنَ عَبْدِ اللَّهِ، بْنِ عُمَرَ يَقُولُ يَا أَهْلَ الْعِرَاقِ مَا أَسْأَلَكُمْ عَنِ الصَّغِيرَةِ وَأَرْكَبَكُمْ لِلْكَبِيرَةِ سَمِعْتُ أَبِي عَبْدَ اللَّهِ بْنَ عُمَرَ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ إِنَّ الْفِتْنَةَ تَجِيءُ مِنْ هَا هُنَا ‏\"‏ ‏.‏ وَأَوْمَأَ بِيَدِهِ نَحْوَ الْمَشْرِقِ ‏\"‏ مِنْ حَيْثُ يَطْلُعُ قَرْنَا الشَّيْطَانِ ‏\"‏ ‏.‏ وَأَنْتُمْ يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ وَإِنَّمَا قَتَلَ مُوسَى الَّذِي قَتَلَ مِنْ آلِ فِرْعَوْنَ خَطَأً فَقَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ ‏{‏ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَاكَ مِنَ الْغَمِّ وَفَتَنَّاكَ فُتُونًا‏}‏ قَالَ أَحْمَدُ بْنُ عُمَرَ فِي رِوَايَتِهِ عَنْ سَالِمٍ لَمْ يَقُلْ سَمِعْتُ ‏.‏","v":[]}],"47":[{"c":"Sahih Muslim","r":"Hadith 185a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-185a","x":"It is reported by Abu Sa'id that the Messenger of Allah (ﷺ) said:\n\nThe (permanent) inhabitants of the Fire are those who are doomed to it, and verily they would neither die nor live in it (al-Qur'an, xx. 47; lxxxvii. 13). But the people whom the Fire would afflict (temporarily) on account of their sins, or so said (the narrator)\" on account of their misdeeds,\" He would cause them to die till they would be turned into charcoal. Then they would be granted intercession and would be brought in groups and would be spread on the rivers of Paradise and then it would be said: O inhabitants of Paradise, pour water over them; then they would sprout forth like the sprouting of seed in the silt carried by flood. A man among the people said: (It appears) as if the Messenger of Allah lived in the steppe.","ar":"وَحَدَّثَنِي نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، حَدَّثَنَا بِشْرٌ، - يَعْنِي ابْنَ الْمُفَضَّلِ - عَنْ أَبِي مَسْلَمَةَ، عَنْ أَبِي نَضْرَةَ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لاَ يَمُوتُونَ فِيهَا وَلاَ يَحْيَوْنَ وَلَكِنْ نَاسٌ أَصَابَتْهُمُ النَّارُ بِذُنُوبِهِمْ - أَوْ قَالَ بِخَطَايَاهُمْ - فَأَمَاتَهُمْ إِمَاتَةً حَتَّى إِذَا كَانُوا فَحْمًا أُذِنَ بِالشَّفَاعَةِ فَجِيءَ بِهِمْ ضَبَائِرَ ضَبَائِرَ فَبُثُّوا عَلَى أَنْهَارِ الْجَنَّةِ ثُمَّ قِيلَ يَا أَهْلَ الْجَنَّةِ أَفِيضُوا عَلَيْهِمْ ‏.‏ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي حَمِيلِ السَّيْلِ ‏\"\n\n‏ ‏.‏ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ كَأَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ كَانَ بِالْبَادِيَةِ ‏.‏","v":[]}],"64":[{"c":"Muwatta Malik","r":"Book 20, Hadith 902","u":"https://quranx.com/Hadith/Malik/In-Book/Book-20/Hadith-902","x":"Yahya related to me from Malik from Ibn Shihab that Salim ibn Abdullah said, ''Abd al-Malik ibn Marwan wrote to al-Hajjaj ibn Yusuf telling him not to disagree with Abdullah ibn Umar about anything to do with the hajj. Then, when the day of Arafa came Abdullah ibn Umar went to him just after noon, and I went with him. He called out to him outside his tent, 'Where is this man?' and a-lHajjaj came out to him, wearing a blanket dyed with safflower, and said to him, 'What's up with you, Abu Abd ar-Rahman?' He said, 'Hurry up, if you want to follow the sunna.' Al-Hajjaj said, 'At this hour?' and he said, 'Yes.' Al-Hajjaj said, 'Wait until I have poured some water over myself, and then I will come out.' So Abdullah dismounted and waited until al- Hajjaj came out. He passed between me and my father and I said to him, 'If you want to accord with the sunna today, then make the khutba short, do not delay the prayer and do the prayer quickly.' Then he began looking at Abdullah ibn Umar to see if he would say the same thing, and when Abdullah saw that, he said, 'What Salim is saying is true.' \" 20.64 Doing the Prayer at Mina on the Eighth Day of Dhu-l-Hijja, and the Jumua at Mina and Arafa","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ قَالَ كَتَبَ عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ إِلَى الْحَجَّاجِ بْنِ يُوسُفَ أَنْ لاَ تُخَالِفَ عَبْدَ اللَّهِ بْنَ عُمَرَ فِي شَىْءٍ مِنْ أَمْرِ الْحَجِّ ‏.‏ قَالَ فَلَمَّا كَانَ يَوْمُ عَرَفَةَ جَاءَهُ عَبْدُ اللَّهِ بْنُ عُمَرَ حِينَ زَالَتِ الشَّمْسُ وَأَنَا مَعَهُ فَصَاحَ بِهِ عِنْدَ سُرَادِقِهِ أَيْنَ هَذَا فَخَرَجَ عَلَيْهِ الْحَجَّاجُ وَعَلَيْهِ مِلْحَفَةٌ مُعَصْفَرَةٌ فَقَالَ مَا لَكَ يَا أَبَا عَبْدِ الرَّحْمَنِ فَقَالَ الرَّوَاحَ إِنْ كُنْتَ تُرِيدُ السُّنَّةَ ‏.‏ فَقَالَ أَهَذِهِ السَّاعَةَ قَالَ نَعَمْ ‏.‏ قَالَ فَأَنْظِرْنِي حَتَّى أُفِيضَ عَلَىَّ مَاءً ثُمَّ أَخْرُجَ ‏.‏ فَنَزَلَ عَبْدُ اللَّهِ حَتَّى خَرَجَ الْحَجَّاجُ فَسَارَ بَيْنِي وَبَيْنَ أَبِي فَقُلْتُ لَهُ إِنْ كُنْتَ تُرِيدُ أَنْ تُصِيبَ السُّنَّةَ الْيَوْمَ فَاقْصُرِ الْخُطْبَةَ وَعَجِّلِ الصَّلاَةَ - قَالَ - فَجَعَلَ يَنْظُرُ إِلَى عَبْدِ اللَّهِ بْنِ عُمَرَ كَيْمَا يَسْمَعَ ذَلِكَ مِنْهُ فَلَمَّا رَأَى ذَلِكَ عَبْدُ اللَّهِ قَالَ صَدَقَ سَالِمٌ ‏.‏","v":[]}],"130":[{"c":"Sahih Muslim","r":"Hadith 633a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-633a","x":"Jarir b. Abdullah is reported to have said:\n\nWe were sitting with the Messenger of Allah (ﷺ) that he looked at the full moon and observed: You shall see your Lord as you are seeing this moon, and you will not be harmed by seeing Him. So if you can, do not let -yourselves be overpowered in case of prayer observed before the rising of the sun and its setting, i. e. the 'Asr prayer and the morning prayer. Jarir then recited it:\" Celebrate the praise of thy Lord before the rising of the sun and before Its setting\" (xx. 130).","ar":"وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ، أَخْبَرَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، حَدَّثَنَا قَيْسُ بْنُ أَبِي حَازِمٍ، قَالَ سَمِعْتُ جَرِيرَ بْنَ عَبْدِ اللَّهِ، وَهُوَ يَقُولُ كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ ‏\"‏ أَمَا إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لاَ تُضَامُّونَ فِي رُؤْيَتِهِ فَإِنِ اسْتَطَعْتُمْ أَنْ لاَ تُغْلَبُوا عَلَى صَلاَةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏\"‏ ‏.‏ يَعْنِي الْعَصْرَ وَالْفَجْرَ ثُمَّ قَرَأَ جَرِيرٌ ‏{‏ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا‏}‏ ‏.‏","v":[]}]};